import{_ as a,a0 as p,w as i,s as u,I as t,x as s,a1 as r,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151027 How to Use SSHfs to Mount a Remote Filesystem on Linux","title":"如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統","tag":"201511","desc":""},"relativePath":"201511/20151027 How to Use SSHfs to Mount a Remote Filesystem on Linux.md","filePath":"[post].md"}'),f={name:"201511/20151027 How to Use SSHfs to Mount a Remote Filesystem on Linux.md"};function d(m,e,S,h,x,w){const o=p("Link");return i(),u("div",null,[e[17]||(e[17]=t("h1",{id:"如何在-linux-上使用-sshfs-掛載一個遠程文件系統",tabindex:"-1"},[s("如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統 "),t("a",{class:"header-anchor",href:"#如何在-linux-上使用-sshfs-掛載一個遠程文件系統","aria-label":"Permalink to “如何在 Linux 上使用 SSHfs 掛載一個遠程文件系統”"},"​")],-1)),e[18]||(e[18]=t("p",null,"你曾經想過用安全 shell 掛載一個遠程文件系統到本地嗎？如果有的話，SSHfs 也許就是你所需要的。它通過使用 SSH 和 Fuse（LCTT 譯註：Filesystem in Userspace，用户態文件系統，是 Linux 中用於掛載某些網絡空間，如 SSH，到本地文件系統的模組） 允許你掛載遠程計算機（或者服務器）到本地。",-1)),t("p",null,[e[1]||(e[1]=t("strong",null,"注意",-1)),e[2]||(e[2]=s("： 這篇文章假設你明白",-1)),r(o,{href:"https://www.maketecheasier.com/setup-ssh-ubuntu/"},{default:n(()=>[...e[0]||(e[0]=[s("SSH 如何工作並在你的系統中配置 SSH",-1)])]),_:1}),e[3]||(e[3]=s("。",-1))]),e[19]||(e[19]=l(`<h3 id="準備" tabindex="-1">準備 <a class="header-anchor" href="#準備" aria-label="Permalink to “準備”">​</a></h3><p>在使用 SSHfs 掛載之前，需要進行一些設置 - 在你的系統上安裝 SSHfs 以及 fuse 軟件包。你還需要為 fuse 創建一個組，添加用户到組，並創建遠程文件系統將會駐留的目錄。</p><p>要在 Ubuntu Linux 上安裝兩個軟件包，只需要在終端窗口輸入以下命令：</p><pre><code>sudo apt-get install sshfs fuse
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-install-fuse-ubuntu.jpg" alt="ubuntu 安裝 sshfs-fuse"></p><p>如果你使用的不是 Ubuntu，那就在你的發行版軟件包管理器中搜索軟件包名稱。最好搜索和 fuse 或 SSHfs 相關的關鍵字，因為取決於你運行的系統，軟件包名稱可能稍微有些不同。</p><p>在你的系統上安裝完軟件包之後，就該創建好 fuse 組了。在你安裝 fuse 的時候，應該會在你的系統上創建一個組。如果沒有的話，在終端窗口中輸入以下命令以便在你的 Linux 系統中創建組：</p><pre><code>sudo groupadd fuse
</code></pre><p>添加了組之後，把你的用户添加到這個組。</p><pre><code>sudo gpasswd -a &quot;$USER&quot; fuse
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-add-user-to-fuse-group.png" alt="sshfs 添加用户到組 fuse"></p><p>別擔心上面命令的 <code>$USER</code>。shell 會自動用你自己的用户名替換。處理了和組相關的工作之後，就是時候創建要掛載遠程文件的目錄了。</p><pre><code>mkdir ~/remote_folder
</code></pre><p>在你的系統上創建了本地目錄之後，就可以通過 SSHfs 掛載遠程文件系統了。</p><h3 id="掛載遠程文件系統" tabindex="-1">掛載遠程文件系統 <a class="header-anchor" href="#掛載遠程文件系統" aria-label="Permalink to “掛載遠程文件系統”">​</a></h3><p>要在你的機器上掛載遠程文件系統，你需要在終端窗口中輸入一段較長的命令。</p><pre><code>sshfs -o idmap=user username@ip.address:/remote/file/system/ ~/remote
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-mount-file-system-to-local-folder.png" alt="sshfs 掛載文件系統到本地目錄1"></p><p><strong>注意</strong>： 也可以通過 SSH 密鑰文件掛載 SSHfs 文件系統。只需要在上面的命中用 <code>sshfs -o IdentityFile=~/.ssh/keyfile</code>, 替換 <code>sshfs -o idmap=user</code> 部分。</p><p>輸入這個命令之後，會提示你輸入遠程用户的密碼。如果登錄成功了，你的遠程文件系統就會被掛載到之前創建的 <code>~/remote_folder</code> 目錄。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-mount-file-system-to-local-folder-2.jpg" alt="sshfs掛載文件系統到本地目錄2"></p><p>使用完了你的遠程文件系統，想要卸載它？容易嗎？只需要在終端輸入下面的命令：</p><pre><code>sudo umount ~/remote_folder
</code></pre><p>這個簡單的命令會斷開遠程連接同時清空 remote_folder 目錄。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在 Linux 上有很多工具可以用於訪問遠程文件並掛載到本地。但是如之前所説，如果有的話，也只有很少的工具能充分利用 SSH 的強大功能。我希望在這篇指南的幫助下，也能認識到 SSHfs 是一個多麼強大的工具。</p><p>你覺得 SSHfs 怎麼樣呢？在下面的評論框裏告訴我們吧！</p><hr>`,28)),t("p",null,[e[5]||(e[5]=s("via: ",-1)),r(o,{href:"https://www.maketecheasier.com/sshfs-mount-remote-filesystem-linux/"},{default:n(()=>[...e[4]||(e[4]=[s("https://www.maketecheasier.com/sshfs-mount-remote-filesystem-linux/",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=s("作者：",-1)),r(o,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:n(()=>[...e[6]||(e[6]=[s("Derrik Diener",-1)])]),_:1}),e[10]||(e[10]=s(" 譯者：",-1)),r(o,{href:"http://mutouxiaogui.cn/blog/"},{default:n(()=>[...e[7]||(e[7]=[s("ictlyh",-1)])]),_:1}),e[11]||(e[11]=s(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[8]||(e[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=s("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[12]||(e[12]=[s("LCTT",-1)])]),_:1}),e[15]||(e[15]=s(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...e[13]||(e[13]=[s("Linux中國",-1)])]),_:1}),e[16]||(e[16]=s(" 榮譽推出",-1))])])}const g=a(f,[["render",d]]);export{T as __pageData,g as default};
